+// API keys, roles and the audit log. Keys live in `apiKeys` as
+// { key, name, role }; roles are ordered, each may do what the ones before it
+// may. Every request that changes data leaves one audit entry; entries are
+// never edited or deleted.
+import { timingSafeEqual } from "node:crypto";
+
+/** Roles from least to most allowed. */
+export const ROLES = ["viewer", "cook", "manager"];
+
+/** The API key record for `key`, or null when there is none. */
+export function findKey(store, key) {
+  if (typeof key !== "string" || key === "") return null;
+  const given = Buffer.from(key);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    const known = Buffer.from(String(k.key ?? ""));
+    if (known.length === given.length && timingSafeEqual(known, given) && ROLES.includes(k.role)) found = k;
+  }
+  return found;
+}
+
+/** Whether `role` is at least the `needed` role. */
+export function allows(role, needed) {
+  const have = ROLES.indexOf(role);
+  return have >= 0 && have >= ROLES.indexOf(needed);
+}
+
+/** Appends an audit entry { id, at, key, method, path, status } and returns it. */
+export function recordAudit(store, { at, key, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, key, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].reverse();
+}
