+++ b/tests/auth.test.js
@@ -0,0 +1,70 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, auth } from "./helpers.js";
+
+test("no key or an unknown key is 401 in the error shape", async () => {
+  const { raw, store } = app();
+  const none = await raw({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  assert.ok(none.body.error.message);
+  const wrong = await raw({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(wrong.status, 401);
+  const before = JSON.stringify(store.data.batches);
+  const post = await raw({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(post.status, 401);
+  assert.equal(JSON.stringify(store.data.batches), before);
+  assert.equal((store.data.audit ?? []).length, 0);
+});
+
+test("viewers only read", async () => {
+  const { handle, store } = app(undefined, { as: "viewer" });
+  assert.equal((await handle({ path: "/items" })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("cooks cook, waste, log temperatures and count, but nothing else", async () => {
+  const { handle } = app(undefined, { as: "cook" });
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/6/waste", body: { qty: 0.5, reason: "spill" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [] } })).status, 403);
+  assert.equal((await handle({ method: "PUT", path: "/items/1/allergens", body: { allergens: [] } })).status, 403);
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("cooks enter stock-take counts a manager started", async () => {
+  const { handle, store } = app();
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  const { handle: cook } = app(store, { as: "cook" });
+  assert.equal((await cook({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 6, counted: 12 } })).status, 200);
+  assert.equal((await cook({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 403);
+});
+
+test("changes are audited, newest first, for managers", async () => {
+  const { handle, store } = app();
+  await handle({ path: "/items" });
+  const { handle: cook } = app(store, { as: "cook" });
+  await cook({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await cook({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [] } });
+  const res = await handle({ path: "/audit?x=1" });
+  assert.equal(res.status, 200);
+  assert.deepEqual(res.body.map(({ key, method, path, status }) => ({ key, method, path, status })), [
+    { key: "line cook", method: "POST", path: "/orders", status: 403 },
+    { key: "line cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+  ]);
+  assert.equal(res.body[0].at, "2026-10-28T10:00:00.000Z");
+  assert.equal(JSON.stringify(res.body).includes("seed-cook-key"), false);
+});
+
+test("the bearer scheme is case-insensitive and the header name too", async () => {
+  const { raw } = app();
+  const res = await raw({ path: "/items", headers: { Authorization: auth("viewer").authorization.replace("Bearer", "bearer") } });
+  assert.equal(res.status, 200);
+});
